INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(33611061, 'Bujinunity', '武神集结', '武神集結', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上没有这张卡以外的卡存在的场合才能发动。自己墓地的名字带有「武神」的兽战士族怪兽全部回到卡组，自己手卡全部送去墓地。那之后，可以从卡组把最多3只卡名不同的名字带有「武神」的兽战士族怪兽加入手卡。「武神集结」在1回合只能发动1张。'),
(36088082, 'Bull Blader', '公牛剑士', 'ブルブレーダー', 'Effect Monster', 'Warrior', 'EARTH', 4, 1600, 1200, '这张卡和对方怪兽进行战斗的攻击宣言时才能发动。那次战斗发生的对双方玩家的战斗伤害变成0，伤害计算后那只对方怪兽破坏。'),
(19974890, 'Bunch of Beast Bodies', '兽痕累累', '獣累々', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：把这个回合没有召唤·特殊召唤的场上的怪兽全部变成守备表示。这个回合，自身场上有守备表示怪兽存在的玩家不能用这个回合召唤·特殊召唤的怪兽攻击宣言。'),
(69380702, 'Bunilla', '香甜兔', 'バニーラ', 'Normal Monster', 'Beast', 'EARTH', 1, 150, 2050, '非常喜欢甜食的甜食派兔子。在找据说是世界第一甜的甘糖胡萝卜，无论今天还是明天都想要啃胡萝卜。'),
(39643167, 'Bunny Ear Enthusiast', '兔耳导师', 'ウサミミ導師', 'Effect Monster', 'Beast-Warrior', 'EARTH', 1, 200, 100, '①：「兔耳导师」以外的场上的怪兽的效果发动时才能发动（同一连锁上最多1次）。给那只怪兽放置1个兔耳指示物。有兔耳指示物放置的怪兽不会被战斗破坏。 ②：1回合1次，以有兔耳指示物放置的1只怪兽为对象才能发动。那只怪兽和这张卡直到下个回合的准备阶段除外。这个效果在对方回合也能发动。'),
(44947065, 'Burden of the Mighty', '强者的苦痛', '強者の苦痛', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：对方场上的怪兽的攻击力下降那怪兽的等级×100。'),
(86690572, 'Burgeoning Whirlflame', '炎涡的胎动', '炎渦の胎動', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '从手卡把1只名字带有「熔岩」的怪兽送去墓地发动。陷阱卡的发动无效并破坏。此外，这张卡在墓地存在的场合，可以把自己墓地存在的2只炎属性怪兽从游戏中除外，这张卡加入手卡。'),
(6297941, 'Burglar', '强盗鼠', 'バーグラー', 'Normal Monster', 'Beast', 'EARTH', 3, 850, 800, '奸诈狡猾的老鼠。使用左手的大钩爪进行攻击。'),
(89974735, 'Burgundy the Magic Elf', '魔法妖精 勃艮第', '魔法妖精 バーガンディ', 'Effect Monster', 'Spellcaster', 'DARK', 4, 1600, 1400, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在怪兽区域存在的状态，对方手卡被效果丢弃的场合才能发动。给与对方那个数量×400伤害。 ②：这张卡被战斗破坏送去墓地时才能发动。对方手卡随机1张丢弃。'),
(34149150, 'Burial Bicorn Carnovorus', '葬角之食肉牛龙', '葬角のカルノヴルス', 'Synchro Tuner Monster', 'Dinosaur', 'FIRE', 6, 2000, 200, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的主要阶段以及战斗阶段才能发动。用包含这张卡的自己场上的怪兽为素材进行1只恐龙族同调怪兽的同调召唤。 ②：自己或对方的怪兽的攻击宣言时才能发动。从手卡把1只恐龙族怪兽无视召唤条件特殊召唤。这个效果的发动后，直到回合结束时自己不是恐龙族怪兽不能特殊召唤。'),
(48976825, 'Burial from a Different Dimension', '从异次元的埋葬', '異次元からの埋葬', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：从除外的自己以及对方的怪兽之中以合计最多3只为对象才能发动。那些怪兽回到墓地。'),
(53797637, 'Burner, Dragon Ruler of Sparks', '炎征龙－燃烧', '炎征竜－バーナー', 'Effect Monster', 'Dragon', 'FIRE', 3, 1000, 200, '这个卡名的效果1回合只能使用1次。 ①：把1只龙族或炎属性的怪兽和这张卡从手卡丢弃才能发动。从卡组把1只「焰征龙-爆龙」特殊召唤。这个效果特殊召唤的怪兽在这个回合不能攻击。'),
(41859700, 'Burning Algae', '燃藻', '燃える藻', 'Effect Monster', 'Pyro', 'FIRE', 3, 500, 1500, '当这张卡被送去墓地时，对方回复1000基本分。'),
(55870497, 'Burning Bamboo Sword', '燃烧竹光', '燃え竹光', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：这张卡已在魔法与陷阱区域存在的状态，自己把「竹光」卡发动的场合才能发动。下次的对方主要阶段1跳过。'),
(59364406, 'Burning Beast', '灼岩魔兽', '灼岩魔獣', 'Union Effect Monster', 'Pyro', 'FIRE', 4, 1500, 1000, '1回合只有1次在自己的主要阶段可以当作装备卡使用给自己的「冰岩魔兽」装备，或者把装备解除以表侧攻击表示特殊召唤。只在这个效果当作装备卡使用时，装备怪兽对对方造成战斗伤害的场合，破坏场上1张表侧表示的魔法或者陷阱卡。（1只怪兽可以装备的同盟最多1张。装备怪兽被战斗破坏的场合，作为代替把这张卡破坏。）'),
(8085950, 'Burning Dragon', '燃烧龙', 'バーニング・ドラゴン', 'Effect Monster', 'Dragon', 'FIRE', 8, 2500, 2100, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡存在，对方场上有怪兽2只以上存在的场合才能发动。这张卡特殊召唤。 ②：这张卡召唤·特殊召唤成功的场合，从手卡丢弃1张魔法卡才能发动。场上的魔法·陷阱卡全部破坏。'),
(46898368, 'Burning Draw', '汹涌的燃烧抽牌', '逆巻く炎の宝札', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名在规则上也当作「转生炎兽」卡使用。这个卡名的卡在1回合只能发动1张，这张卡发动的回合，自己不是炎属性怪兽不能召唤·特殊召唤。 ①：对方场上的卡数量比自己场上的卡多的场合，以对方场上1只连接怪兽为对象才能发动。自己抽出那只怪兽的连接标记的数量。'),
(24294108, 'Burning Land', '燃烧的大地', '燃えさかる大地', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡的发动时，场上的场地魔法卡全部破坏。此外，双方的准备阶段时，回合玩家受到500分伤害。'),
(26293219, 'Burning Skull Head', '燃烧骷髅头', 'バーニング・スカルヘッド', 'Effect Monster', 'Zombie', 'FIRE', 3, 1000, 800, '这张卡从手卡特殊召唤成功时，给与对方基本分1000分伤害。此外，可以把自己场上表侧表示存在的这张卡从游戏中除外，从游戏中除外的1只「骷髅炎鬼」回到墓地。'),
(10723472, 'Burning Soul', '燃烧之魂', 'バーニング・ソウル', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有8星以上的同调怪兽存在的场合才能发动。「燃烧之魂」以外的自己墓地1张卡加入手卡。那之后，进行1只同调怪兽的同调召唤。这张卡的发动后，直到回合结束时对方不能把场上的同调怪兽作为效果的对象。'),
(18937875, 'Burning Spear', '灼热之枪', '灼熱の槍', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '炎属性的怪兽才能装备。装备的怪兽攻击力上升400，守备力下降200。'),
(25669282, 'Burnout', '完全燃烧', '完全燃焼', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '「完全燃烧」在1回合只能发动1张。 ①：把自己场上1只表侧表示的「化合兽」怪兽除外才能发动。从卡组把2只「化合兽」怪兽特殊召唤（同名卡最多1张）。 ②：对方怪兽的直接攻击宣言时，把墓地的这张卡除外，以除外的1只自己的二重怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽当作再1次召唤的状态使用。这个效果在这张卡送去墓地的回合不能发动。'),
(80163754, 'Burst Breath', '爆裂龙息', 'バーストブレス', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：把自己场上1只龙族怪兽解放才能发动。持有解放的怪兽的攻击力以下的守备力的场上的怪兽全部破坏。'),
(50243722, 'Burst Rebirth', '爆裂埋伏', 'バースト・リバース', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：支付2000基本分，以自己墓地1只怪兽为对象才能发动。那只怪兽里侧守备表示特殊召唤。'),
(27191436, 'Burst Return', '爆热归还', 'バースト・リターン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '「元素英雄 爆热女郎」在自己场上表侧表示存在时才能发动。场上的「元素英雄 爆热女郎」以外的名字带有「元素英雄」的怪兽全部回到持有者的手卡。'),
(17655904, 'Burst Stream of Destruction', '毁灭的爆裂疾风弹', '滅びの爆裂疾風弾', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这张卡发动的回合，自己不能用「青眼白龙」攻击。 ①：自己场上有「青眼白龙」存在的场合才能发动。对方场上的怪兽全部破坏。'),
(42429678, 'Bururu @Ignister', '风萧萧＠伊格尼斯者', 'ブルル＠イグニスター', 'Tuner Monster', 'Cyberse', 'WIND', 3, 600, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把1只「@火灵天星」怪兽送去墓地。 ②：这张卡作为电子界族同调怪兽的同调素材送去墓地的场合，以「抖抖妖@火灵天星」以外的自己墓地1只作为那次同调召唤的素材的怪兽为对象才能发动。那只怪兽特殊召唤。'),
(78193831, 'Buster Blader', '破坏之剑士', 'バスター・ブレイダー', 'Effect Monster', 'Warrior', 'EARTH', 7, 2600, 2300, '①：这张卡的攻击力上升对方的场上·墓地的龙族怪兽数量×500。'),
(3428069, 'Buster Blader, the Destruction Swordmaster', '使破坏剑的高手-破坏之剑士', '破壊剣の使い手－バスター・ブレイダー', 'Effect Monster', 'Warrior', 'EARTH', 7, 2600, 2300, '①：这张卡的卡名只要在场上·墓地存在当作「破坏之剑士」使用。 ②：对方场上的怪兽被战斗·效果破坏送去墓地的场合，以破坏的那1只怪兽为对象才能发动。那只怪兽当作装备卡使用给这张卡装备。 ③：1回合1次，把这张卡装备的1张怪兽卡送去墓地才能发动。和送去墓地的那张怪兽卡相同种族的对方场上的怪兽全部破坏。'),
(86240887, 'Buster Blader, the Dragon Destroyer Swordsman', '龙破坏的剑士-破坏之剑士', '竜破壊の剣士－バスター・ブレイダー', 'Fusion Monster', 'Warrior', 'LIGHT', 8, 2800, 2500, '「破坏之剑士」＋龙族怪兽 这张卡不用融合召唤不能特殊召唤。 ①：这张卡不能直接攻击。 ②：这张卡的攻击力·守备力上升对方的场上·墓地的龙族怪兽数量×1000。 ③：只要这张卡在怪兽区域存在，对方场上的龙族怪兽变成守备表示，对方不能把龙族怪兽的效果发动。 ④：这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。'),
(63676256, 'Buster Blaster', '破坏炮击人', 'バスター・ショットマン', 'Union Effect Monster', 'Machine', 'EARTH', 1, NULL, NULL, '1回合1次，自己的主要阶段时可以当作装备卡使用给自己场上的怪兽装备，或者把装备解除以表侧攻击表示特殊召唤。只在这个效果当作装备卡使用的场合，装备怪兽的攻击力·守备力下降500。装备怪兽战斗破坏对方怪兽的场合，场上表侧表示存在的和破坏的怪兽相同种族的怪兽全部破坏。（1只怪兽可以装备的同盟最多1张。装备怪兽被破坏的场合，作为代替把这张卡破坏。）'),
(11790356, 'Buster Dragon', '破戒蛮龙-破坏龙', '破戒蛮竜－バスター・ドラゴン', 'Synchro Monster', 'Dragon', 'DARK', 8, 1200, 2800, '调整＋调整以外的怪兽1只以上 ①：对方场上的怪兽只要这张卡表侧表示存在变成龙族。 ②：自己场上没有「破坏之剑士」怪兽存在的场合，1回合1次，以自己墓地1只「破坏之剑士」为对象才能发动。那只怪兽特殊召唤。 ③：对方回合1次，以自己场上1只「破坏之剑士」怪兽为对象才能发动。自己墓地1只「破坏剑」怪兽当作装备卡使用给作为对象的怪兽装备。'),
(4998619, 'Buster Gundil the Cubic Behemoth', '方界超兽 破坏之乾闼尔', '方界超獣バスター・ガンダイル', 'Effect Monster', 'Beast', 'LIGHT', 4, NULL, NULL, '这张卡不能通常召唤。把自己场上3只「方界」怪兽送去墓地的场合才能特殊召唤。 ①：这个方法特殊召唤的这张卡的攻击力上升3000。 ②：这张卡在同1次的战斗阶段中可以作3次攻击。 ③：这张卡被对方送去墓地的场合，以自己墓地最多3只「方界」怪兽为对象才能发动。那些怪兽特殊召唤。那之后，可以从自己的卡组·墓地选1张「方界」卡加入手卡。'),
(84740193, 'Buster Rancher', '破坏炮', 'バスターランチャー', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '这张卡只能装备在攻击力1000以下的怪兽上。伤害计算时，对方怪兽攻击表示则看攻击力，守备表示则看守备力，其数值在2500以上时，装备这张卡的怪兽攻击力上升2500。'),
(49823708, 'Buster Whelp of the Destruction Swordsman', '破坏剑士的伴龙', '破壊剣士の伴竜', 'Tuner Monster', 'Dragon', 'LIGHT', 1, 400, 300, '这个卡名的②③的效果1回合只能有1次使用其中任意1个。 ①：这张卡召唤成功时才能发动。从卡组把「破坏剑士的伴龙」以外的1张「破坏剑」卡加入手卡。 ②：把这张卡解放才能发动。从自己的手卡·墓地选1只「破坏之剑士」特殊召唤。 ③：这张卡在墓地存在，自己场上有「破坏之剑士」存在的场合，从手卡丢弃1张「破坏剑」卡才能发动。这张卡特殊召唤。'),
(83991690, 'Buten', '天猪福', 'ブーテン', 'Tuner Monster', 'Fairy', 'LIGHT', 1, 200, 300, '自己的主要阶段时，把墓地存在的这张卡从游戏中除外，选择自己场上表侧表示存在的1只4星以下的天使族·光属性怪兽才能发动。选择的怪兽只要在场上表侧表示存在当作调整使用。'),
(69243953, 'Butterfly Dagger - Elma', '蝶之短剑-回音', '蝶の短剣－エルマ', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '装备这张卡的怪兽攻击力上升300点。装备在怪兽身上的这张卡被破坏送去墓地时，这张卡可以弹回持有者手卡。'),
(58288565, 'Butterfly Fish', '蝴蝶鱼人', 'バタフライ・フィッシュ', 'Effect Monster', 'Fish', 'WATER', 3, 700, 400, '这个卡名的①②的效果1回合只能有1次使用其中任意1个，这些效果发动的回合，自己不是水属性怪兽不能从额外卡组特殊召唤。 ①：这张卡为让怪兽的效果发动而被送去墓地的场合才能发动。这张卡加入手卡。 ②：这张卡在墓地存在的状态，怪兽被战斗以外送去自己墓地的场合，把1张手卡丢弃去墓地才能发动。这张卡特殊召唤。'),
(75987257, 'Butterflyoke', '隶属鳞粉', '隷属の鱗粉', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方怪兽的攻击宣言时才能发动。攻击怪兽的表示形式变成守备表示，那1只怪兽把这张卡装备。此外，1回合1次，主要阶段以及战斗阶段时才能发动。装备怪兽的表示形式变更。'),
(63630268, 'Butterspy Protection', '幻蝶的守护', '幻蝶の護り', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择场上表侧攻击表示存在的1只怪兽才能发动。选择的怪兽变成表侧守备表示。这张卡发动的回合，自己受到的全部伤害变成一半。'),
(7150545, 'Buzzsaw Shark', '切割鲨', 'カッター・シャーク', 'Effect Monster', 'Fish', 'WATER', 4, 1600, 500, '这个卡名的①的效果1回合只能使用1次。 ①：以自己场上1只水属性怪兽为对象才能发动。和那只怪兽是卡名不同并是等级相同的1只鱼族怪兽从卡组守备表示特殊召唤。这个效果特殊召唤的怪兽在这个回合不能把效果发动。这个效果的发动后，直到回合结束时自己不是超量怪兽不能从额外卡组特殊召唤。 ②：把这张卡在水属性怪兽的超量召唤使用的场合，可以把这张卡的等级当作3星或5星使用。'),
(35011819, 'By Order of the Emperor', '帝皇勒令', 'エンペラー・オーダー', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：需怪兽召唤成功时发动的怪兽的效果发动时才能把这个效果发动。那个发动无效。那之后，发动无效的玩家从卡组抽1张。'),
(20735371, 'Bye Bye Damage', '倍倍伤害', 'バイバイダメージ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的效果1回合只能适用1次。 ①：自己怪兽被攻击的伤害计算时才能发动。那只自己怪兽不会被那次战斗破坏。那次战斗让自己受到战斗伤害时，对方受到那个数值2倍的效果伤害。'),
(36935434, 'Byroad Sacrifice', '小道里的牲祭', 'バイロード・サクリファイス', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上的怪兽被战斗破坏的场合才能发动。从手卡特殊召唤1只「电子食人魔」。'),
(17597059, 'Byser Shock', '电击拷问机', 'バイサー・ショック', 'Effect Monster', 'Fiend', 'DARK', 5, 800, 600, '这张卡召唤·反转召唤·特殊召唤成功时，将场上的所有盖放的卡回到持有者的手卡。'),
(72656408, 'Bystial Baldrake', '渊兽 巴尔德雷克', '深淵の獣バルドレイク', 'Effect Monster', 'Dragon', 'DARK', 6, 2500, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己或者对方的墓地1只光·暗属性怪兽为对象才能发动（对方场上有怪兽存在的场合，这个效果在对方回合也能发动）。那只怪兽除外，这张卡从手卡特殊召唤。 ②：对方把仪式·融合·同调·超量·连接怪兽特殊召唤的场合，把自己场上1只其他的光·暗属性怪兽解放，以那1只特殊召唤的怪兽为对象才能发动。那只怪兽除外。'),
(27572350, 'Bystial Dis Pater', '神渊兽 迪斯・帕忒耳', '深淵の神獣ディス・パテル', 'Synchro Monster', 'Dragon', 'DARK', 10, 3500, 3500, '调整＋调整以外的龙族怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：以自己或对方的除外状态的1只光·暗属性怪兽为对象才能发动。那只怪兽在自己场上特殊召唤。 ②：对方把怪兽的效果发动时，以自己或对方的除外状态的1张卡为对象才能发动。那张卡回到卡组。并且，作为对象的卡的持有者是自己的场合，再把那只怪兽破坏。是对方的场合，再把那个发动的效果无效。'),
(6637331, 'Bystial Druiswurm', '渊兽 德尔伊德布鲁姆', '深淵の獣ドルイドヴルム', 'Effect Monster', 'Dragon', 'DARK', 6, 2500, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己或对方的墓地1只光·暗属性怪兽为对象才能发动（对方场上有怪兽存在的场合，这个效果在对方回合也能发动）。那只怪兽除外，这张卡从手卡特殊召唤。 ②：这张卡从场上送去墓地的场合，以对方场上1只特殊召唤的怪兽为对象才能发动。那只怪兽送去墓地。'),
(33854624, 'Bystial Magnamhut', '渊兽 玛格纳姆特', '深淵の獣マグナムート', 'Effect Monster', 'Dragon', 'DARK', 6, 2500, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己或对方的墓地1只光·暗属性怪兽为对象才能发动（对方场上有怪兽存在的场合，这个效果在对方回合也能发动）。那只怪兽除外，这张卡从手卡特殊召唤。 ②：这张卡特殊召唤的场合才能发动。这个回合的结束阶段，从自己的卡组·墓地把「深渊之兽 玛格巨龙」以外的1只龙族怪兽加入手卡。'),
(60242223, 'Bystial Saronir', '渊兽 萨罗尼尔', '深淵の獣サロニール', 'Effect Monster', 'Dragon', 'DARK', 6, 2500, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己或对方的墓地1只光·暗属性怪兽为对象才能发动（对方场上有怪兽存在的场合，这个效果在对方回合也能发动）。那只怪兽除外，这张卡从手卡特殊召唤。 ②：这张卡被送去墓地的场合才能发动。「深渊之兽 萨隆魔龙」以外的1只「深渊之兽」怪兽或1张「烙印」魔法·陷阱卡从卡组送去墓地。'),
(3405259, 'C-Crush Wyvern', 'C－粉碎翼龙', 'C－クラッシュ・ワイバーン', 'Union Effect Monster', 'Machine', 'LIGHT', 4, 1200, 2000, '①：1回合1次，可以把1个以下效果发动。 ●以自己场上1只机械族·光属性怪兽为对象，把这张卡当作装备魔法卡使用来装备。装备怪兽被战斗·效果破坏的场合，作为代替把这张卡破坏。 ●装备状态的这张卡特殊召唤。 ②：装备怪兽不受对方的陷阱卡的效果影响。 ③：这张卡从场上送去墓地的场合才能发动。从手卡把1只同盟怪兽特殊召唤。'),
(91449144, 'Caam, Serenity of Gusto', '薰风的静寂 卡姆', 'ガスタの静寂 カーム', 'Effect Monster', 'Psychic', 'WIND', 4, 1700, 1100, '1回合1次，可以让自己墓地存在的2只名字带有「薰风」的怪兽回到卡组，从自己卡组抽1张卡。'),
(84384943, 'Cabrera Stone', '卡布雷拉石', 'カブレラストーン', 'Effect Monster', 'Rock', 'EARTH', 1, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡召唤·反转召唤·特殊召唤的场合才能发动。从卡组把1张「三角阵-O」加入手卡。这张卡是攻击表示的场合，再让这张卡变成守备表示。 ②：这张卡被战斗·效果破坏的场合发动。自己受到1000伤害。'),
(31615285, 'Cactus Bouncer', '仙人掌终结者', 'サボウ・クローザー', 'Effect Monster', 'Plant', 'EARTH', 4, 1800, 300, '这张卡不能特殊召唤。只要这张卡以外的植物族怪兽在场上表侧表示存在，双方不能把怪兽特殊召唤。'),
(74440055, 'Cactus Fighter', '小仙人掌斗士', 'サボウ・ファイター', 'Effect Monster', 'Plant', 'EARTH', 4, 1900, 400, '这张卡战斗破坏对方怪兽的场合，在对方场上把1只「针衍生物」（植物族·地·1星·攻/守500）守备表示特殊召唤。'),
(9342162, 'Cagna, Malebranche of the Burning Abyss', '彼岸恶鬼 哈洛杭德', '彼岸の悪鬼 ハロウハウンド', 'Effect Monster', 'Fiend', 'DARK', 3, 1500, 300, '「彼岸的恶鬼 卡尼亚佐」的①③的效果1回合只能有1次使用其中任意1个。 ①：自己场上没有魔法·陷阱卡存在的场合才能发动。这张卡从手卡特殊召唤。 ②：自己场上有「彼岸」怪兽以外的怪兽存在的场合这张卡破坏。 ③：这张卡被送去墓地的场合才能发动。从卡组把1张「彼岸」魔法·陷阱卡送去墓地。'),
(21501505, 'Cairngorgon, Antiluminescent Knight', '暗迁士 黑晶戈贡', '暗遷士 カンゴルゴーム', 'XYZ Monster', 'Rock', 'DARK', 4, 2450, 1950, '4星怪兽×2 ①：只以场上的卡1张为对象的其他的魔法·陷阱·怪兽的效果发动时，把这张卡1个超量素材取除，以场上1张作为正确对象的别的卡为对象才能发动。那个效果的对象转移为作为正确对象的那张卡。'),
(87288189, 'Caius the Mega Monarch', '怨邪帝盖乌斯', '怨邪帝ガイウス', 'Effect Monster', 'Fiend', 'DARK', 8, 2800, 1000, '这张卡可以把1只上级召唤的怪兽解放作上级召唤。 ①：这张卡上级召唤成功的场合，以场上1张卡为对象发动。那张卡除外，给与对方1000伤害。除外的卡是暗属性怪兽卡的场合，从那控制者的手卡·卡组·额外卡组·墓地把同名卡全部除外。这张卡把暗属性怪兽解放作上级召唤成功的场合，那个时候的效果加上以下效果。 ●这个效果的对象可以变成2张。'),
(9748752, 'Caius the Shadow Monarch', '邪帝盖乌斯', '邪帝ガイウス', 'Effect Monster', 'Fiend', 'DARK', 6, 2400, 1000, '①：这张卡上级召唤成功的场合，以场上1张卡为对象发动。那张卡除外，除外的卡是暗属性怪兽卡的场合，给与对方1000伤害。'),
(73213494, 'Calcab, Malebranche of the Burning Abyss', '彼岸恶鬼 哈克斯帕', '彼岸の悪鬼 ハックルスパー', 'Effect Monster', 'Fiend', 'DARK', 3, 1400, NULL, '「彼岸的恶鬼 卡尔卡布里纳」的①③的效果1回合只能有1次使用其中任意1个。 ①：自己场上没有魔法·陷阱卡存在的场合才能发动。这张卡从手卡特殊召唤。 ②：自己场上有「彼岸」怪兽以外的怪兽存在的场合这张卡破坏。 ③：这张卡被送去墓地的场合，以场上盖放的1张魔法·陷阱卡为对象才能发动。盖放的那张卡回到持有者手卡。'),
(67692580, 'Caligo Claw Crow', '黑爪乌鸦', 'クロクロークロウ', 'Effect Monster', 'Winged Beast', 'DARK', 2, 900, 600, '这个卡名的①的方法的特殊召唤1回合只能有1次。 ①：自己场上有暗属性怪兽存在的场合，这张卡可以从手卡特殊召唤。'),
(78637313, 'Call of Darkness', '来自黑暗的呼声', '闇からの呼び声', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '「死者苏生」的效果特殊召唤的怪兽全部送去墓地。只要这张卡在场上存在，「死者苏生」不能使用。'),
(97803170, 'Call of the Archfiend', '恶魔的呼唤', 'デーモンの呼び声', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：以自己墓地1只5星以上的恶魔族怪兽为对象才能发动。从手卡丢弃1只恶魔族怪兽，作为对象的怪兽特殊召唤。'),
(73199638, 'Call of the Atlanteans', '海皇的咆哮', '海皇の咆哮', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '选择自己墓地3只3星以下的海龙族怪兽才能发动。选择的3只怪兽从墓地特殊召唤。这张卡发动的回合，自己不能把怪兽特殊召唤。'),
(65743242, 'Call of the Earthbound', '地缚灵的引诱', '地縛霊の誘い', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方怪兽的攻击宣言时才能发动。那个攻击对象由自己重新选择。'),
(16970158, 'Call of the Grave', '来自墓场的呼声', '墓場からの呼び声', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方把「死者苏生」发动时才能发动。那张「死者苏生」的效果无效。'),
(97077563, 'Call of the Haunted', '活死人的呼唤', 'リビングデッドの呼び声', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：以自己墓地1只怪兽为对象才能把这张卡发动。那只怪兽攻击表示特殊召唤。这张卡从场上离开时那只怪兽破坏。那只怪兽破坏时这张卡破坏。'),
(300101003, 'Call of the Haunted (Skill Card)', NULL, NULL, 'Skill Card', 'Bonz', NULL, NULL, NULL, NULL, NULL),
(4861205, 'Call of the Mummy', '木乃伊的呼声', 'ミイラの呼び声', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，自己主要阶段才能发动。从手卡把1只不死族怪兽特殊召唤。这个效果在自己场上没有怪兽存在的场合才能发动和处理。'),
(45133463, 'Call of the Reaper', '死神的呼声', '死神の呼び声', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '从自己墓地有怪兽特殊召唤时才能发动。选择自己墓地存在的1只「苏帕伊」或者「赤蚁」特殊召唤。'),
(24224830, 'Called by the Grave', '墓穴指名者', '墓穴の指名者', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：以对方墓地1只怪兽为对象才能发动。那只怪兽除外。直到下个回合的结束时，这个效果除外的怪兽以及原本卡名和那只怪兽相同的怪兽的效果无效化。'),
(51773900, 'Calming Magic', '宁神魔法', 'カーム・マジック', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '主要阶段一的开始时才能发动。那个回合的主要阶段时以及战斗阶段时，双方玩家不能把怪兽通常召唤·反转召唤·特殊召唤。'),
(15635751, 'Camelot, Realm of Noble Knights and Noble Arms', '圣骑士与圣剑的巨城', '聖騎士と聖剣の巨城', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：自己主要阶段才能发动。这张卡直到下次的准备阶段除外，从自己的手卡·卡组·墓地把1张「圆桌的圣骑士」在自己的场地区域表侧表示放置。那之后，以下效果可以适用。 ●从自己的卡组·墓地把1只「阿托利斯」怪兽特殊召唤或把1张「圣剑」卡加入手卡。 ②：1回合1次，自己场上的「圣骑士」卡被战斗·效果破坏的场合，可以作为代替把自己场上1张装备卡破坏。'),
(5244497, 'Cameraclops', '独家新闻摄影师', 'スクープ・シューター', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1400, 1600, '这张卡向持有比这张卡的攻击力高的守备力的场上表侧表示存在的怪兽攻击的场合，不进行伤害计算把那只怪兽破坏。'),
(47695416, 'Candle of Fate', '命运之蜡烛', '運命のろうそく', 'Normal Monster', 'Fiend', 'DARK', 2, 600, 600, '指尖的火焰消失时，将决定对方的命运。'),
(91754175, 'Caninetaur', '人犬兽', '犬タウルス', 'Effect Monster', 'Beast-Warrior', 'FIRE', 3, 1500, 200, '①：1回合1次，这张卡和对方怪兽进行战斗的伤害计算时才能发动。从手卡·卡组把1只兽族·兽战士族·鸟兽族怪兽送去墓地，这张卡的攻击力直到战斗阶段结束时上升送去墓地的那只怪兽的等级×100。'),
(11384280, 'Cannon Soldier', '加农炮兵', 'キャノン・ソルジャー', 'Effect Monster', 'Machine', 'DARK', 4, 1400, 1300, '可以把自己场上存在的1只怪兽解放，给与对方基本分500分伤害。'),
(14702066, 'Cannon Soldier MK-2', '大型加农炮兵', 'メガキャノン・ソルジャー', 'Effect Monster', 'Machine', 'EARTH', 5, 1900, 1200, '每把自己场上存在的2只怪兽作为祭品，给与对方基本分1500分伤害。'),
(95614612, 'Cannonball Spear Shellfish', '炮弹枪贝', '砲弾ヤリ貝', 'Effect Monster', 'Aqua', 'WATER', 2, 1000, 1000, '当场上存在「海」时，这张卡不受魔法效果的影响。'),
(16021142, 'Canon the Melodious Diva', '幻奏音女 珈诺', '幻奏の音女カノン', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1400, 2000, '「幻奏的音女 卡农」的①的方法的特殊召唤1回合只能有1次。 ①：自己场上有「幻奏」怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：1回合1次，以自己场上1只「幻奏」怪兽为对象才能发动。那只怪兽的表示形式变更。'),
(1490690, 'Canopic Protector', '卡诺匹斯的保卫者', 'カノプスの守護者', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：对方把效果发动时才能发动（同一连锁上最多1次）。从自己的手卡·墓地把1只「荷鲁斯」怪兽特殊召唤。这个回合，自己不能把原本卡名和这个效果特殊召唤的怪兽相同的怪兽用「卡诺匹斯的守护者」的效果特殊召唤。 ②：这张卡从手卡·场上送去墓地的场合才能发动。这张卡在自己场上盖放。这个效果盖放的这张卡从场上离开的场合除外。'),
(28120197, 'Canyon', '断层地带', '断層地帯', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '守备表示的岩石族怪兽被攻击，攻击怪兽的控制者受到战斗伤害的场合，那个战斗伤害变成2倍。'),
(29716911, 'Capacitor Stalker', '电容跟踪杀人蝎', 'コンデンサー・デスストーカー', 'Effect Monster', 'Cyberse', 'LIGHT', 5, 2000, 1000, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡召唤成功时，以这张卡以外的自己场上1只电子界族怪兽为对象才能发动。这只怪兽表侧表示存在期间，那只怪兽的攻击力上升800。 ②：怪兽区域的这张卡被效果破坏送去墓地的场合发动。双方玩家受到800伤害。'),
(55289183, 'Capricious Darklord', '享乐的堕天使', '享楽の堕天使', 'Effect Monster', 'Fairy', 'DARK', 4, NULL, 1600, '这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的主要阶段才能发动。把1只天使族怪兽表侧表示上级召唤。 ②：这张卡被送去墓地的场合才能发动。对方场上的全部怪兽的攻击力·守备力直到回合结束时下降场上的天使族怪兽数量×500。'),
(76722334, 'Capshell', '扭蛋魔壳', 'カプシェル', 'Effect Monster', 'Fiend', 'DARK', 2, NULL, NULL, '这个卡名的①②③的效果1回合只能有1次使用其中任意1个。 ①：这张卡被解放的场合才能发动。自己抽1张。 ②：这张卡成为融合·同调·连接召唤的素材，被送去墓地的场合或者被除外的场合才能发动。自己抽1张。 ③：超量素材的这张卡为让超量怪兽的效果发动而被取除的场合才能发动。自己抽1张。'),
(37806313, 'Caravan of the Ice Barrier', '冰结界的运输部队', '氷結界の輸送部隊', 'Effect Monster', 'Sea Serpent', 'WATER', 1, 500, 200, '①：1回合1次，以自己墓地2只「冰结界」怪兽为对象才能发动。那2只怪兽回到卡组。那之后，双方各自抽1张。'),
(15981690, 'Carboneddon', '碳素龙', 'カーボネドン', 'Effect Monster', 'Dinosaur', 'EARTH', 3, 800, 600, '「碳素龙」的②的效果1回合只能使用1次。 ①：这张卡和炎属性怪兽进行战斗的伤害计算时发动。这张卡的攻击力只在那次伤害计算时上升1000。 ②：自己主要阶段把墓地的这张卡除外才能发动。从手卡·卡组把1只7星以下的龙族通常怪兽守备表示特殊召唤。'),
(52112003, 'Card Advance', '上级卡片', 'カード・アドバンス', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：从自己卡组上面把最多5张卡确认，用喜欢的顺序回到卡组上面。这个回合自己在通常召唤外加上只有1次可以把1只怪兽上级召唤。'),
(42256406, 'Card Blocker', '卡片防卫士', 'カードブロッカー', 'Effect Monster', 'Warrior', 'EARTH', 3, 400, 400, '这张卡召唤·反转召唤·特殊召唤成功时，变成守备表示。自己场上表侧表示存在的怪兽被选择作为攻击对象时，可以让攻击对象改变为这张卡。这张卡成为攻击对象时，可以把自己卡组的卡从上面最多3张送去墓地。每把1张卡送去墓地，这张卡的守备力直到结束阶段时上升500。'),
(51047350, 'Card Breaker', '卡片破坏者', 'カード・ブレイカー', 'Effect Monster', 'Warrior', 'LIGHT', 2, 100, 900, '这张卡不能通常召唤。把自己的魔法与陷阱卡区域存在的1张卡送去墓地的场合可以表侧攻击表示特殊召唤。'),
(72892473, 'Card Destruction', '手牌抹杀', '手札抹殺', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：有手卡的玩家把那些手卡全部丢弃。那之后，那些玩家抽出自身丢弃的数量。'),
(26701483, 'Card Ejector', '卡片除外士', 'カードエクスクルーダー', 'Effect Monster', 'Spellcaster', 'EARTH', 3, 400, 400, '选择对方墓地存在的1张卡从游戏中除外。这个效果1回合只能使用1次。'),
(4694209, 'Card Guard', '卡片守卫', 'カードガード', 'Effect Monster', 'Fiend', 'DARK', 4, 1600, 500, '这张卡召唤·特殊召唤成功时，给这张卡放置1个守卫指示物。这张卡放置的守卫指示物每有1个，这张卡的攻击力上升300。此外，1回合1次，可以把这张卡放置的1个守卫指示物取除，并给这张卡以外的自己场上表侧表示存在的1张卡放置1个守卫指示物。选择的卡被破坏的场合，作为代替把1个守卫指示物取除。'),
(59750328, 'Card of Demise', '削命宝牌', '命削りの宝札', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这张卡发动的回合，自己不能把怪兽特殊召唤。 ①：自己直到手卡变成3张为止从卡组抽卡。这张卡的发动后，直到回合结束时对方受到的全部伤害变成0。这个回合的结束阶段，自己手卡全部送去墓地。'),
(74191528, 'Card of Fate', '命运之一枚', '運命の一枚', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：双方从自身卡组选1张卡。那之后，双方把对方卡组的卡随机选4张。双方各自把自身选的1张卡和对方选的4张混合洗切，从那5张之中随机选1张，给双方确认，加入自身手卡。剩下的卡回到自身卡组。'),
(88513608, 'Card of Sacrifice', '舍身的宝札', '捨て身の宝札', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上表侧攻击表示存在的怪兽2只以上的攻击力合计比对方场上表侧表示存在的攻击力最低的怪兽低的场合，从自己卡组抽2张卡。这张卡发动的回合，自己不能把怪兽召唤·反转召唤·特殊召唤，也不能把表示形式变更。'),
(57953380, 'Card of Safe Return', '生还的宝札', '生還の宝札', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '自己墓地存在的怪兽特殊召唤成功时，可以从自己卡组抽1张卡。'),
(42664989, 'Card of Sanctity', '天降的宝札', '天よりの宝札', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：把自己的手卡·场上的卡全部除外才能发动。自己直到手卡变成2张为止从卡组抽卡。'),
(7044562, 'Card of the Soul', '魂之卡', '魂のカード', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '「魂之卡」在1回合只能发动1张。 ①：把自己卡组确认。可以从那之中把1只攻击力·守备力的合计是和自己基本分相同数值的怪兽加入手卡。'),
(72767833, 'Card Rotator', '卡片反转者', 'カード・フリッパー', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '把1张手卡送去墓地发动。把对方场上存在的全部怪兽的表示形式改变。'),
(77066768, 'Card Scanner', '卡片扫描者', 'カードスキャナー', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，宣言1个卡的种类（怪兽·魔法·陷阱）才能发动。双方玩家各自把自身卡组最下面的卡给双方确认，宣言的种类的场合，那卡加入自身手卡。不是的场合，确认的卡在自身卡组最上面放置。 ②：魔法与陷阱区域的表侧表示的这张卡被对方的效果破坏的场合才能发动。对方选自身1张手卡回到卡组最下面。'),
(12183332, 'Card Shuffle', '霰弹式洗牌', 'ショット・ガン・シャッフル', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '支付300基本分。自己或对方洗1次卡组。这个效果1回合只能使用1次。'),
(48712195, 'Card Trader', '卡片商人', 'カードトレーダー', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '自己的准备阶段时可以让1张手卡回到卡组，从自己卡组抽1张卡。这个效果1回合只能使用1次。'),
(85087012, 'Card Trooper', '卡片炮击士', 'カードガンナー', 'Effect Monster', 'Machine', 'EARTH', 3, 400, 400, '①：1回合1次，从自己卡组上面把最多3张卡送去墓地才能发动。这张卡的攻击力直到回合结束时上升因为这个效果发动而送去墓地的卡数量×500。 ②：自己场上的这张卡被破坏送去墓地的场合发动。自己抽1张。'),
(45812361, 'Cardcar D', '卡片汽车·D', 'カードカー・D', 'Effect Monster', 'Machine', 'EARTH', 2, 800, 400, '这张卡不能特殊召唤。这张卡的效果发动的回合，自己不能把怪兽特殊召唤。 ①：这张卡召唤的自己主要阶段1把这张卡解放才能发动。自己抽2张。那之后，变成这个回合的结束阶段。'),
(4168871, 'Cards for Black Feathers', '黑羽之宝札', '黒羽の宝札', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '从手卡把1只名字带有「黑羽」的怪兽从游戏中除外发动。从自己卡组抽2张卡。这张卡发动的回合，自己不能把怪兽特殊召唤。「黑羽之宝札」在1回合只能发动1张。'),
(54977057, 'Cards from the Sky', '天空的宝札', '天空の宝札', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这张卡发动的回合，自己不能把怪兽特殊召唤，不能进行战斗阶段。 ①：从手卡把1只天使族·光属性怪兽除外，自己从卡组抽2张。'),
(39701395, 'Cards of Consonance', '调和的宝牌', '調和の宝札', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：从手卡丢弃1只攻击力1000以下的龙族调整才能发动。自己从卡组抽2张。'),
(32566831, 'Cards of the Red Stone', '红玉的宝牌', '紅玉の宝札', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '「红玉之宝札」在1回合只能发动1张。 ①：从手卡把1只7星「真红眼」怪兽送去墓地才能发动。自己从卡组抽2张。那之后，可以从卡组把1只7星「真红眼」怪兽送去墓地。'),
(13567610, 'Carnot the Eternal Machine', '无穷机龙 卡诺', '無窮機竜カルノール', 'Effect Monster', 'Machine', 'LIGHT', 10, 3000, 2500, '这张卡不能通常召唤。对方是这次决斗中有把手卡或墓地的怪兽的效果发动过的场合可以从手卡·墓地特殊召唤。自己对「无穷机龙 卡诺循环龙」1回合只能有1次特殊召唤。 ①：1回合1次，对方把怪兽的效果发动的场合才能发动。这张卡的攻击力上升1000。 ②：这张卡从手卡·卡组以外送去墓地的场合发动。这张卡回到卡组。'),
(85055821, 'Carpiponica, Mystical Beast of the Forest', '森之圣兽 千斤榆熊', '森の聖獣 カルピポニカ', 'Effect Monster', 'Beast', 'EARTH', 7, 1000, 2600, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡从手卡送去墓地的场合，以这张卡以外的自己墓地的兽族·兽战士族·鸟兽族·昆虫族·植物族怪兽合计2只为对象才能发动（相同种族最多1只）。那些怪兽回到卡组，这张卡特殊召唤。 ②：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把「森之圣兽 熊四手兽」以外的1只「森之圣兽」怪兽或者「森之圣灵」怪兽加入手卡。'),
(46848859, 'Carrierroid', '航空母舰机人', 'ネイビィロイド', 'Effect Monster', 'Machine', 'WATER', 4, 1000, 800, '对方以自己场上的魔法·陷阱卡为对象把持有使场上的魔法·陷阱卡破坏效果的卡发动时，可以丢弃1张手卡，那张卡的发动和效果无效并破坏。'),
(94076521, 'Cartorhyn the Hidden Gem of the Seafront', '水界的秘石－卡特林', '水界の秘石－カトリン', 'Effect Monster', 'Rock', 'WATER', 2, 500, 1600, '这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡从手卡丢弃才能发动。这个回合，自己在通常召唤外加上只有1次，自己主要阶段可以把1只地·水属性怪兽召唤。 ②：这张卡在墓地存在，自己场上有地属性怪兽以及水属性怪兽存在的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(59957503, 'Cash Back', '现金返还', 'キャッシュバック', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '对方支付基本分发动的效果怪兽的效果·魔法·陷阱卡的发动无效，那张卡回到持有者卡组。'),
(12527118, 'Cassimolar', '卡西莫拉尔', 'カシモラル', 'Effect Monster', 'Fiend', 'DARK', 3, 1000, 1200, '①：这张卡召唤成功时，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力上升那个原本攻击力数值。这个效果适用的怪兽在下个回合的结束阶段破坏，对方受到那个原本攻击力一半数值的伤害。 ②：对方战斗阶段开始时，把通常召唤的这张卡解放才能发动。这个回合，对方怪兽不能直接攻击。'),
(82633039, 'Castel, the Skyblaster Musketeer', '鸟铳士卡斯戴尔', '鳥銃士カステル', 'XYZ Monster', 'Winged Beast', 'WIND', 4, 2000, 1500, '4星怪兽×2 这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：把这张卡1个超量素材取除，以场上1只表侧表示怪兽为对象才能发动。那只怪兽变成里侧守备表示。 ②：把这张卡2个超量素材取除，以场上1张其他的表侧表示卡为对象才能发动。那张卡回到卡组。'),
(36931229, 'Castle Gate', '城堡之门', 'キャッスル・ゲート', 'Effect Monster', 'Rock', 'EARTH', 6, NULL, 2400, '①：这张卡不会被战斗破坏。 ②：1回合1次，这张卡在场上攻击表示存在的场合，把自己场上1只5星以下的怪兽解放才能发动。给与对方解放的怪兽的原本攻击力数值的伤害。'),
(22198672, 'Castle Link', '王车连接', 'キャッスル・リンク', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：1回合1次，自己主要阶段以场上1只连接怪兽为对象才能发动。那只怪兽的位置向那只怪兽所连接区的主要怪兽区域移动（不能向从那只怪兽来看的对方场上移动）。 ②：1回合1次，自己主要阶段才能发动。选自己的主要怪兽区域2只连接怪兽或者对方的主要怪兽区域2只连接怪兽，那些位置交换。'),
(62121, 'Castle of Dark Illusions', '暗晦之城', '闇晦ましの城', 'Flip Effect Monster', 'Fiend', 'DARK', 4, 920, 1930, '反转：场上表侧表示的全部不死族的怪兽攻击力·守备力加200。只要这张卡在场上表侧表示存在，自己的每个准备阶段不死族的攻守力都会加200。这个效果持续到自己的第4个准备阶段。'),
(13513663, 'Castle of Dragon Souls', '龙魂之城', '竜魂の城', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：「龙魂之城」在自己场上只能有1张表侧表示存在。 ②：1回合1次，从自己墓地把1只龙族怪兽除外，以自己场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时上升700。 ③：表侧表示的这张卡从场上送去墓地时，以除外的1只自己的龙族怪兽为对象才能发动。那只怪兽特殊召唤。'),
(44209392, 'Castle Walls', '城壁', '城壁', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择场上表侧表示存在的1只怪兽发动。选择的怪兽的守备力直到结束阶段时上升500。'),
(84224627, 'Cat Shark', '猫鲨', 'キャット・シャーク', 'XYZ Monster', 'Beast', 'WATER', 2, 500, 500, '2星怪兽×2 ①：这张卡持有水属性怪兽作为超量素材的场合，这张卡不会被战斗破坏。 ②：1回合1次，把这张卡1个超量素材取除，以自己场上1只4阶以下的超量怪兽为对象才能发动。那只怪兽的攻击力·守备力直到回合结束时变成原本数值的2倍。这个效果在对方回合也能发动。'),
(95841282, 'Cat''s Ear Tribe', '猫耳族', 'ネコ耳族', 'Effect Monster', 'Beast-Warrior', 'EARTH', 1, 200, 100, '对方回合时，与这张卡战斗的怪兽的原本攻击力在伤害步骤时变成200。'),
(62850093, 'Cataclysmic Circumpolar Chilblainia', '冰天祸 奇尔布莱恩', '氷天禍チルブレイン', 'Effect Monster', 'Fairy', 'WATER', 8, 2600, 200, '这个卡名的效果1回合只能使用1次。 ①：自己场上的表侧表示的水属性怪兽被战斗或者对方的效果破坏的场合才能发动。这张卡从手卡特殊召唤。那之后，可以把对方手卡随机选1张送去墓地。'),
(9028399, 'Cataclysmic Crusted Calcifida', '乐天祸 卡尔克拉格拉', '楽天禍カルクラグラ', 'Effect Monster', 'Fairy', 'EARTH', 8, 2600, 200, '这个卡名的效果1回合只能使用1次。 ①：自己场上的表侧表示的地属性怪兽被战斗或者对方的效果破坏的场合才能发动。这张卡从手卡特殊召唤。那之后，可以从卡组把1只怪兽送去墓地。'),
(19420830, 'Cataclysmic Cryonic Coldo', '满天祸 科尔德', '満天禍コルドー', 'Effect Monster', 'Fairy', 'WIND', 8, 2600, 200, '这个卡名的效果1回合只能使用1次。 ①：自己场上的表侧表示的风属性怪兽被战斗或者对方的效果破坏的场合才能发动。这张卡从手卡特殊召唤。那之后，可以选场上1张魔法·陷阱卡回到持有者卡组最上面。'),
(39505816, 'Cataclysmic Scorching Sunburner', '炎天祸 桑伯恩', '炎天禍サンバーン', 'Effect Monster', 'Fairy', 'FIRE', 8, 2600, 200, '这个卡名的效果1回合只能使用1次。 ①：自己场上的表侧表示的炎属性怪兽被战斗或者对方的效果破坏的场合才能发动。这张卡从手卡特殊召唤。那之后，可以选那1只破坏的自己墓地的炎属性怪兽，给与对方那个攻击力一半数值的伤害。'),
(65959844, 'Catalyst Field', '化合电界', '化合電界', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：只要这张卡在场地区域存在，自己在5星以上的二重怪兽召唤的场合需要的解放可以不用。这个效果1回合只能适用1次。 ②：只要这张卡在场地区域存在，自己在通常召唤外加上只有1次，自己主要阶段可以把1只二重怪兽召唤。 ③：1回合1次，以对方场上1张卡为对象才能发动。自己场上1只再1次召唤状态的二重怪兽直到对方结束阶段除外，作为对象的卡破坏。'),
(95727991, 'Catapult Turtle', '弹射龟', 'カタパルト・タートル', 'Effect Monster', 'Aqua', 'WATER', 5, 1000, 2000, '1回合1次，把自己场上1只怪兽解放才能发动。给与对方基本分解放的怪兽的攻击力一半数值的伤害。'),
(37474917, 'Catapult Warrior', '弹射战士', 'カタパルト・ウォリアー', 'Synchro Monster', 'Warrior', 'EARTH', 5, 1000, 1500, '调整＋调整以外的怪兽1只以上 把自己场上存在的1只名字带有「废品」的怪兽解放发动。给与对方基本分解放的怪兽的原本攻击力数值的伤害。这个效果1回合只能使用1次。'),
(14289852, 'Catapult Zone', '投石区', '岩投げエリア', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：只要这张卡在场地区域存在，自己怪兽被战斗破坏的场合，可以作为代替从自己卡组把1只岩石族怪兽送去墓地。这个效果1回合只能适用1次。'),
(300102003, 'Catch of the Day', NULL, NULL, 'Skill Card', 'Mako', NULL, NULL, NULL, NULL, NULL),
(50690129, 'Catche Eve L2', '缓存猫・二级等', 'キャシー・イヴL２', 'Effect Monster', 'Cyberse', 'LIGHT', 2, 800, 600, '这个卡名的效果1回合只能使用1次。 ①：这张卡在手卡存在的场合，以自己场上1只3星以上的怪兽为对象才能发动。那只怪兽的等级下降2星，这张卡特殊召唤。'),
(96501677, 'Catnipped Kitty', '木天蓼猫', 'またたびキャット', 'Effect Monster', 'Beast', 'EARTH', 2, NULL, 500, '自己场上有这张卡以外的兽族怪兽存在的场合，不能攻击这张卡。把对方场上存在的1只怪兽守备力在回合结束前变为0。这个效果1回合只能使用1次。'),
(54360049, 'Catoblepas and the Witch of Fate', '卡托布莱帕斯与命运之魔女', 'カトブレパスと運命の魔女', 'Effect Monster', 'Spellcaster', 'EARTH', 4, 1800, NULL, '对方对怪兽的特殊召唤成功时，可以把自己墓地存在的1只攻击力是?的怪兽从游戏中除外，那些特殊召唤的怪兽破坏。'),
(45955628, 'Catoblepas, Familiar of the Evil Eye', '咒眼之眷属 卡托布莱帕斯', '呪眼の眷属 カトブレパス', 'Effect Monster', 'Fiend', 'DARK', 3, 600, 1900, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上1张「咒眼」魔法·陷阱卡为对象才能发动。直到下个回合的结束时，那张卡只有1次不会被对方的效果破坏。 ②：这张卡在墓地存在，自己场上有「咒眼之眷属 卡托布莱帕斯」以外的「咒眼」怪兽存在的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(50619462, 'Cattle Call', '乌合无象', '烏合無象', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己场上把1只原本种族是兽族·兽战士族·鸟兽族的表侧表示怪兽送去墓地才能发动。原本种族和送去墓地的那只怪兽相同的1只怪兽从额外卡组特殊召唤。这个效果特殊召唤的怪兽不能攻击，效果无效化，结束阶段破坏。'),
(61245403, 'Cattycorn', '猫玉米', 'ネコーン', 'Effect Monster', 'Plant', 'EARTH', 4, 1500, 500, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤成功的场合，若自己的场地区域没有卡存在则能发动。从卡组把1张场地魔法卡加入手卡。 ②：这张卡被战斗·效果破坏送去墓地的场合，以自己墓地1张场地魔法卡为对象才能发动。把1张那张卡的同名卡从卡组加入手卡。'),
(91740879, 'Cauldron of the Old Man', '隐居者的大釜', 'ご隠居の大釜', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：作为这张卡的发动时的效果处理，给这张卡放置1个指示物。 ②：自己准备阶段发动。给这张卡放置1个指示物。 ③：1回合1次，可以从以下效果选择1个发动。 ●自己回复这张卡的指示物数量×500基本分。 ●给与对方这张卡的指示物数量×300伤害。'),
(93220472, 'Cave Dragon', '巨龙', 'グランド・ドラゴン', 'Effect Monster', 'Dragon', 'WIND', 4, 2000, 100, '这张卡在自己场上至少有1只其他的怪兽存在不能召唤。自己场上没有这张卡以外的龙族怪兽存在时，这张卡不能攻击宣言。'),
(36468556, 'Ceasefire', '停战协定', '停戦協定', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：场上有效果怪兽或者里侧守备表示怪兽存在的场合才能发动。场上的里侧守备表示怪兽全部变成表侧守备表示。这个时候，反转怪兽的效果不发动。给与对方为场上的效果怪兽数量×500伤害。'),
(43912676, 'Celestia', '异层空间', '異層空間', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：场上的幻龙族怪兽的攻击力·守备力上升300。 ②：1回合1次，把自己墓地3只幻龙族怪兽除外，以场上1张卡为对象才能发动。那张卡破坏。'),
(94381039, 'Celestia, Lightsworn Angel', '光道天使 基路比姆', 'ライトロード・エンジェル ケルビム', 'Effect Monster', 'Fairy', 'LIGHT', 5, 2300, 200, '把名字带有「光道」的怪兽解放对这张卡的上级召唤成功时，从自己卡组上面把4张卡送去墓地才能发动。选择对方场上最多2张卡破坏。'),
(54092240, 'Celestial Apparatus Tesea', '至崇圣灵器', 'テセア聖霊器', 'Effect Monster', 'Fairy', 'EARTH', 4, 1000, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有「勇者衍生物」存在的场合才能发动。这张卡从手卡特殊召唤。 ②：把有「勇者衍生物」的衍生物名记述的手卡1张卡给对方观看才能发动。把通常魔法卡以外的有「勇者衍生物」的衍生物名记述的1张魔法卡从卡组加入手卡。这个效果发动的回合，自己若非「勇者衍生物」以及有那个衍生物名记述的怪兽则不能特殊召唤。'),
(25472513, 'Celestial Double Star Shaman', '天轮之双星道士', '天輪の双星道士', 'Synchro Tuner Monster', 'Fairy', 'LIGHT', 2, 100, 800, '调整＋调整以外的怪兽1只 「天轮之双星道士」的效果1回合只能使用1次。 ①：这张卡同调召唤成功时才能发动。从自己的手卡·墓地选最多4只调整以外的2星怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽的效果无效化。这个效果的发动后，直到回合结束时自己不是同调怪兽不能从额外卡组特殊召唤。'),
(48589580, 'Celestial Knightlord Parshath', '天空神骑士 罗德珀耳修斯', '天空神騎士ロードパーシアス', 'Link Monster', 'Fairy', 'LIGHT', NULL, 2400, NULL, '天使族怪兽2只以上 这个卡名的①②的效果1回合各能使用1次。 ①：丢弃1张手卡才能发动。把1张「天空的圣域」或者有那个卡名记述的卡从卡组加入手卡。场上有「天空的圣域」存在的场合，可以把加入手卡的卡改成1只天使族怪兽。 ②：自己场上的表侧表示的天使族怪兽被送去墓地的场合，从自己墓地把1只天使族怪兽除外才能发动。比除外的怪兽等级高的1只天使族怪兽从手卡特殊召唤。'),
(67378104, 'Celestial Observatory', '呼星六分仪', '星呼びの天儀台', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从手卡以及自己场上的表侧表示怪兽之中让1只6星怪兽回到持有者卡组最下面才能发动。自己从卡组抽2张。'),
(55569674, 'Celestial Sword - Eatos', '女神的圣剑-鹰灵', '女神の聖剣－エアトス', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '①：装备怪兽的攻击力上升500。 ②：这张卡从场上送去墓地时，以自己场上1只「守护者·艾托斯」为对象才能发动。那只怪兽的攻击力上升除外中的怪兽数量×500。'),
(28890974, 'Celestial Transformation', '光神化', '光神化', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：从手卡把1只天使族怪兽特殊召唤。这个效果特殊召唤的怪兽的攻击力变成一半，结束阶段破坏。'),
(32995007, 'Celestial Wolf Lord, Blue Sirius', '天狼王 苍狼星', '天狼王 ブルー・セイリオス', 'Synchro Monster', 'Beast-Warrior', 'DARK', 6, 2400, 1500, '调整＋调整以外的怪兽1只以上 场上存在的这张卡被破坏送去墓地时，选择对方场上表侧表示存在的1只怪兽发动。选择的怪兽的攻击力下降2400。'),
(84491298, 'Cell Explosion Virus', '细胞爆破病毒', '細胞爆破ウイルス', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '放置有A指示物的对方怪兽的攻击宣言时才能发动。对方场上存在的攻击表示怪兽全部破坏。'),
(45531624, 'Celtic Guard of Noble Arms', '精灵圣剑士', 'エルフの聖剣士', 'Effect Monster', 'Warrior', 'EARTH', 4, 2100, 700, '这张卡在规则上也当作「精灵剑士」卡使用。 ①：有自己手卡的场合，这张卡不能攻击。 ②：1回合1次，自己主要阶段才能发动。从手卡把1只「精灵剑士」怪兽特殊召唤。 ③：这张卡的攻击给与对方战斗伤害时才能发动。自己从卡组抽出自己场上的「精灵剑士」怪兽的数量。'),
(91152256, 'Celtic Guardian', '精灵剑士', 'エルフの剣士', 'Normal Monster', 'Warrior', 'EARTH', 4, 1400, 1200, '学会了剑术的精灵。以快速的攻击作弄敌人。'),
(51394546, 'Cemetary Bomb', '公墓炸弹', 'セメタリー・ボム', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方受到对方墓地卡数×100的伤害。'),
(33129626, 'Centaur Mina', '半人马米娜', 'ケンタウルミナ', 'Fusion Monster', 'Beast-Warrior', 'LIGHT', 6, 2200, 1600, '战士族·光属性怪兽＋兽族怪兽 这个卡名的①③的效果1回合各能使用1次。 ①：自己主要阶段才能发动。从自己的手卡·墓地选1只2星以下的怪兽特殊召唤。 ②：1回合1次，自己回合对方把陷阱卡发动时才能发动。那个发动无效，那张卡直接盖放。 ③：这张卡作为战士族·风属性同调怪兽的同调素材送去墓地的场合才能发动。选场上1只表侧表示怪兽破坏。'),
(47346782, 'Centerfrog', '反侧青蛙', '寝ガエル', 'Effect Monster', 'Aqua', 'WATER', 2, 100, 2000, '这张卡不能作为融合·同调·超量·连接召唤的素材。 ①：这张卡召唤·反转召唤成功的场合发动。这张卡变成守备表示。 ②：1回合1次，以对方的主要怪兽区域1只怪兽为对象才能发动。守备表示的这张卡向作为对象的对方怪兽的相邻的怪兽区域转移控制权。那之后，对方的主要怪兽区域的「寝青蛙」只有2只的场合，得到那2只的中间存在的全部怪兽的控制权。'),
(1801154, 'Centrifugal Field', '离心分离力场', '遠心分離フィールド', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '融合怪兽因为卡的效果破坏送去墓地时，从自己墓地选择那只融合怪兽记述的1只融合素材，特殊召唤到自己场上。'),
(96030710, 'Centur-Ion Atrii', '龙装百夫骑士 阿特莉', '竜騎士アトリィ', 'Tuner Monster', 'Dragon', 'DARK', 4, 1800, 1400, '这个卡名的①③的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合，若「徽记」卡和「百夫长骑士」卡各在自己墓地存在则能发动。自己抽1张。这个回合，自己不能把「龙骑士 阿特莉」特殊召唤。 ②：把自己场上的这张卡作为同调素材的场合，可以把这张卡当作调整以外的怪兽使用。 ③：这张卡是当作永续陷阱卡使用的场合，自己·对方的主要阶段才能发动。这张卡特殊召唤。'),
(71858682, 'Centur-Ion Auxila', '百夫骑士皇 阿克斯拉', '騎士皇アークシーラ', 'Synchro Monster', 'Dragon', 'DARK', 12, 3000, 3000, '调整＋调整以外的怪兽1只以上 这个卡名的①③的效果1回合各能使用1次。 ①：这张卡特殊召唤的场合才能发动。从卡组把1张「百夫长骑士」卡加入手卡。 ②：只要这张卡在怪兽区域存在，自己的魔法与陷阱区域的表侧表示卡不会被效果破坏。 ③：自己·对方的结束阶段才能发动。同调怪兽以外的自己的墓地·除外状态的1只「百夫长骑士」怪兽当作永续陷阱卡使用在自己的魔法与陷阱区域表侧表示放置。'),
(4160316, 'Centur-Ion Bonds', '百夫骑士之绊', '騎士の絆', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从自己的手卡·墓地把1只「百夫长骑士」怪兽当作永续陷阱卡使用在自己的魔法与陷阱区域表侧表示放置。 ②：这张卡在墓地存在的状态，自己场上有「百夫长骑士」同调怪兽特殊召唤的场合，把这张卡除外，以自己墓地1只「百夫长骑士」怪兽为对象才能发动。那只怪兽当作永续陷阱卡使用在自己的魔法与陷阱区域表侧表示放置。'),
(81696879, 'Centur-Ion Chimerea', '影魔百夫骑士 西梅莉娅', '影騎士シメーリア', 'Effect Monster', 'Pyro', 'DARK', 4, 1200, 1600, '这个卡名的①②的效果1回合各能使用1次。 ①：连锁2以后对方把怪兽的效果发动时才能发动。那个效果变成「对方把自身的场上（表侧表示）·墓地1只「百夫长骑士」怪兽当作永续陷阱卡使用在自身的魔法与陷阱区域表侧表示放置」。这个回合，自己不能把「影骑士 奇美莉娅」特殊召唤。 ②：这张卡是当作永续陷阱卡使用的场合，自己·对方的主要阶段才能发动。这张卡特殊召唤。'),
(78888899, 'Centur-Ion Emeth VI', '重装百夫骑兵 艾梅忒Ⅵ', '重騎兵エメトⅥ', 'Effect Monster', 'Machine', 'EARTH', 8, 2000, 3000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡·墓地存在的场合，对方回合，以「重骑兵 真理6」以外的自己场上1只「百夫长骑士」怪兽为对象才能发动。那只怪兽当作永续陷阱卡使用在自己的魔法与陷阱区域表侧表示放置，这张卡特殊召唤。这个回合，自己不能把「重骑兵 真理6」特殊召唤。 ②：这张卡是当作永续陷阱卡使用的场合，自己·对方的主要阶段才能发动。这张卡特殊召唤。'),
(97698279, 'Centur-Ion Gargoyle II', '龙装百夫骑兵 卡戈尔Ⅱ', '竜騎兵ガーゴイルⅡ', 'Effect Monster', 'Dragon', 'DARK', 8, 2000, 3000, '这个卡名的①②③的效果1回合各能使用1次。 ①：把自己场上1张表侧表示的「百夫长骑士」卡送去墓地才能发动。这张卡从手卡特殊召唤。这个回合，自己不能把「龙骑兵 石像怪2」特殊召唤。 ②：这张卡作为同调素材送去墓地的场合才能发动。这张卡加入手卡。 ③：这张卡是当作永续陷阱卡使用的场合，自己·对方的主要阶段才能发动。这张卡特殊召唤。那之后，可以让这张卡的等级下降4星。'),
(15982593, 'Centur-Ion Legatia', '百夫骑士皇 蕾格提亚', '騎士皇レガーティア', 'Synchro Monster', 'Machine', 'LIGHT', 12, 3500, 2000, '调整＋调整以外的怪兽1只以上 这个卡名的①③的效果1回合各能使用1次。 ①：这张卡特殊召唤的场合才能发动。自己抽1张。那之后，可以把对方场上1只攻击力最高的怪兽破坏。 ②：攻击力2000以下的自己怪兽不会被战斗破坏。 ③：自己·对方的结束阶段才能发动。从自己的手卡·墓地把同调怪兽以外的1只「百夫长骑士」怪兽当作永续陷阱卡使用在自己的魔法与陷阱区域表侧表示放置。'),
(40155014, 'Centur-Ion Phalanx', '百夫骑士魔防阵', '騎士魔防陣', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：以场上1张表侧表示的怪兽卡为对象才能发动。那张卡除外。下个回合的准备阶段，这个效果除外的怪兽在持有者场上特殊召唤。 ②：把墓地的这张卡除外，以自己墓地1只「百夫长骑士」同调怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽的攻击力下降1500。'),
(15005145, 'Centur-Ion Primera', '重装百夫骑士 普莉梅拉', '重騎士プリメラ', 'Tuner Monster', 'Spellcaster', 'LIGHT', 4, 1600, 1600, '这个卡名的①③的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组把「重骑士 普莉梅拉」以外的1张「百夫长骑士」卡加入手卡。这个回合，自己不能把「重骑士 普莉梅拉」特殊召唤。 ②：这张卡是当作永续陷阱卡使用的场合，自己场上的5星以上的「百夫长骑士」怪兽不会被效果破坏。 ③：这张卡是当作永续陷阱卡使用的场合，自己·对方的主要阶段才能发动。这张卡特殊召唤。'),
(8841431, 'Centur-Ion Primera Primus', '百夫骑士皇 普莉梅拉・普里默斯', '騎士皇プリメラ・プリムス', 'Synchro Tuner Monster', 'Spellcaster', 'LIGHT', 8, 2600, 2600, '调整＋调整以外的怪兽1只以上 这个卡名的①③的效果1回合各能使用1次。 ①：这张卡同调召唤的场合才能发动。从自己的卡组·墓地把1张「徽记」卡加入手卡。那之后，可以把自己以及对方场上的卡各1张破坏。 ②：从额外卡组以外特殊召唤的这张卡不会被战斗破坏。 ③：自己场上的表侧表示的「百夫长骑士」卡因对方的效果从场上离开的场合才能发动。这张卡从墓地特殊召唤。'),
(42493140, 'Centur-Ion Trudea', '从属百夫骑士 特露蒂亚', '従騎士トゥルーデア', 'Effect Monster', 'Pyro', 'DARK', 4, 1000, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。自己场上的这张卡和除「从骑士 特露迪娅」以外的手卡·卡组1只「百夫长骑士」怪兽当作永续陷阱卡使用在自己的魔法与陷阱区域表侧表示放置。这个回合，自己不能把「从骑士 特露迪娅」特殊召唤。 ②：这张卡是当作永续陷阱卡使用的场合，自己·对方的主要阶段才能发动。这张卡特殊召唤。那之后，可以让这张卡的等级上升4星。'),
(77543769, 'Centur-Ion True Awakening', '百夫骑士皇爆诞', '騎士皇爆誕', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：怪兽的效果·魔法·陷阱卡发动时，把自己的魔法与陷阱区域1张表侧表示的怪兽卡送去墓地才能发动。那个发动无效并破坏。'),
(20228463, 'Ceremonial Bell', '仪典之钟', 'セレモニーベル', 'Effect Monster', 'Spellcaster', 'LIGHT', 3, NULL, 1850, '只要这张卡在场上表侧表示存在，双方玩家把手卡全部持续公开。'),
(82340057, 'Ceremonial Token', '荣誉的祭品', '栄誉の贄', 'Token', 'Rock', NULL, NULL, NULL, NULL, NULL),
(24175232, 'Cerulean Sacred Phoenix of Nephthys', '奈芙蒂斯之苍凰神', 'ネフティスの蒼凰神', 'Ritual Effect Monster', 'Winged Beast', 'FIRE', 8, 3000, 1000, '「奈芙提斯的轮回」降临。这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。从手卡以及自己场上的表侧表示的卡之中选「奈芙提斯」卡任意数量破坏。那之后，选破坏数量的对方场上的怪兽破坏。 ②：这张卡被战斗·效果破坏送去墓地的场合，下次的自己准备阶段才能发动。这张卡从墓地特殊召唤。'),
(54828837, 'Cerulean Skyfire', '失乐霹雳', '失楽の霹靂', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：「降雷皇 哈蒙」用自身的方法特殊召唤的场合，也能把自己场上的里侧表示的魔法卡送去墓地。 ②：1回合1次，自己场上有「降雷皇 哈蒙」攻击表示存在的场合，可以把对方发动的魔法·陷阱卡的效果无效。那之后，选自己场上1只「降雷皇 哈蒙」变成守备表示。 ③：自己场上的表侧表示的「神炎皇 乌利亚」「降雷皇 哈蒙」「幻魔皇 拉比艾尔」的其中任意种从场上离开的场合发动。这个回合，自己受到的全部伤害变成0。'),
(7623640, 'Ceruli, Guru of Dark World', '暗黑界的导师 塞鲁利', '暗黒界の導師 セルリ', 'Effect Monster', 'Fiend', 'DARK', 1, 100, 300, '①：这张卡被效果从手卡丢弃去墓地的场合发动。这张卡在对方场上守备表示特殊召唤。 ②：这张卡用「暗黑界」卡的效果特殊召唤成功的场合发动。对方选自身1张手卡丢弃。'),
(28106077, 'Cestus of Dagla', '达古拉之剑', 'ダグラの剣', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '只有天使族怪兽能装备这张卡。装备这张卡的怪兽攻击力上升500点。装备这张卡的怪兽对对方造成战斗伤害时，自己回复与伤害数值相同的基本分。'),
(83021423, 'Chachaka Archer', '急匆匆弓手', 'チャッチャカアーチャー', 'Effect Monster', 'Warrior', 'WIND', 6, 1200, 1800, '1回合1次，选择场上1张魔法·陷阱卡才能发动。选择的卡破坏。'),
(48276469, 'Chain Burst', '连锁炸药', '連鎖炸薬', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '给与发动陷阱卡的玩家基本分1000分的伤害。'),
(1248895, 'Chain Destruction', '连锁破坏', '連鎖破壊', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：攻击力2000以下的怪兽召唤·反转召唤·特殊召唤时，以那1只表侧表示怪兽为对象才能发动。从那只表侧表示怪兽的控制者的手卡·卡组把作为对象的怪兽的同名卡全部破坏。'),
(51449743, 'Chain Detonation', '连锁爆破', 'チェーン・ブラスト', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '给与对方基本分500分伤害。这张卡在连锁2或者连锁3发动的场合，这张卡加入卡组洗切。这张卡在连锁4以后发动的场合，这张卡回到手卡。'),
(57139487, 'Chain Disappearance', '连锁除外', '連鎖除外', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '攻击力1000以下的怪兽召唤·反转召唤·特殊召唤成功时才能发动。那些攻击力1000以下的怪兽从游戏中除外，再把和除外的卡同名卡从对方的手卡·卡组全部除外。'),
(3171055, 'Chain Dispel', '连锁解咒', '連鎖解呪', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：魔法·陷阱卡发动时才能发动。从发动的那张魔法·陷阱卡的控制者卡组把同名卡全部破坏。'),
(96930127, 'Chain Dog', '链犬', 'チェーンドッグ', 'Effect Monster', 'Beast', 'EARTH', 4, 1600, 1100, '自己场上是兽族怪兽表侧表示2只存在的场合，可以把这张卡从墓地特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合，从游戏中除外。把这张卡作为同调素材的场合，不是兽族怪兽的同调召唤不能使用。'),
(79323590, 'Chain Energy', '魔力之枷', '魔力の枷', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '双方玩家若不支付500基本分，则不能从手卡把卡召唤·特殊召唤·发动·盖放。'),
(25050038, 'Chain Healing', '连锁治愈', 'チェーン・ヒーリング', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己回复500基本分。这张卡在连锁2或者连锁3发动的场合，这张卡加入卡组洗切。这张卡在连锁4以后发动的场合，这张卡回到手卡。'),
(9581215, 'Chain Hole', '连锁空洞', '連鎖空穴', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方连锁魔法·陷阱·怪兽的效果的发动把怪兽的效果发动时才能发动。那个效果无效。那之后，对方可以从手卡·卡组选原本卡名和用这个效果无效的卡相同的1张卡除外。没有除外的场合，自己可以把对方手卡随机选1张除外。'),
(85893201, 'Chain Ignition', '连锁诱爆', '連鎖誘爆', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡在场上存在，对方场上的怪兽被对方的卡的效果破坏的场合，可以选择场上1张卡破坏。这个效果1回合只能使用1次。'),
(39980304, 'Chain Material', '连锁素材', 'チェーン・マテリアル', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这张卡的发动回合自己融合召唤的场合，可以把融合怪兽卡决定的融合素材怪兽从自己的手卡·卡组·场上·墓地选出从游戏中除外，用这些作为融合素材。这张卡发动的回合，自己不能攻击，这个效果融合召唤的怪兽在结束阶段时破坏。'),
(13764881, 'Chain Resonator', '锁链共鸣者', 'チェーン・リゾネーター', 'Tuner Monster', 'Fiend', 'LIGHT', 1, 100, 100, '①：场上有同调怪兽存在，这张卡召唤成功时才能发动。从卡组把「锁链共鸣者」以外的1只「共鸣者」怪兽特殊召唤。'),
(91623717, 'Chain Strike', '连锁爆击', '連鎖爆撃', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '连锁2以后才能发动。给与对方基本分这张卡的发动时积累的连锁数量×400的数值的伤害。同一连锁上有复数次同名卡的效果发动的场合，这张卡不能发动。'),
(90812044, 'Chain Summon', '连锁召唤', '連鎖召喚', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上有超量怪兽2只以上存在的场合，以那之内的1只阶级最低的超量怪兽为对象才能发动。比那只怪兽阶级低的1只超量怪兽从额外卡组特殊召唤。这个效果特殊召唤的怪兽不能直接攻击，结束阶段回到额外卡组。'),
(9952083, 'Chain Summoning', '召唤连锁', 'サモンチェーン', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：同一连锁上没有复数次同名卡的效果发动的场合，那个连锁3以后才能发动。这个回合自己可以进行通常召唤最多3次。'),
(88190453, 'Chain Thrasher', '链击者', 'チェイン・スラッシャー', 'Effect Monster', 'Warrior', 'WIND', 4, 1000, 600, '这张卡可以在通常的攻击之外再增加和自己墓地存在的「链击者」相同的数目，在同1次的战斗阶段中进行攻击。'),
(22205600, 'Chain Whirlwind', '连锁旋风', '連鎖旋風', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '魔法·陷阱·效果怪兽的效果让场上存在的卡破坏时，选择场上存在的2张魔法·陷阱卡才能发动。选择的卡破坏。'),
(77252217, 'Chainsaw Insect', '电动刃虫', '電動刃虫', 'Effect Monster', 'Insect', 'EARTH', 4, 2400, NULL, '这张卡进行战斗的场合，伤害步骤结束时对方玩家抽1张卡。'),
(65393205, 'Chakra', '查克拉', 'チャクラ', 'Ritual Monster', 'Fiend', 'DARK', 7, 2450, 2000, '借由「查克拉的复活」降临。必须从场上或者手札，牺牲奉献等级合计为7个以上的卡。'),
(32600024, 'Chamber Dragonmaid', '龙女仆・客房龙女', 'ドラゴンメイド・チェイム', 'Effect Monster', 'Dragon', 'DARK', 4, 500, 1800, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组把1张「半龙女仆」魔法·陷阱卡加入手卡。 ②：自己·对方的战斗阶段开始时才能发动。这张卡回到手卡，从自己的手卡·墓地把1只7星以上的「半龙女仆」怪兽特殊召唤。'),
(44430454, 'Chamberlain of the Six Samurai', '六武众之侍从', '六武衆の侍従', 'Normal Monster', 'Warrior', 'EARTH', 3, 200, 2000, '暗地里支持六武众的充满谜团的人物。虽然现在已经不再参战，但是刻在身上的无数伤痕诉说着什么。他的过去无人知晓。'),
(46001505, 'Champion''s Pulse', '王者的鼓动', '王者の鼓動', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：可以从以下效果选择1个发动。 ●对方战斗阶段才能发动。对方回复1000基本分。那之后，战斗阶段结束。 ●对方场上的卡数量比自己场上的卡多，对方把怪兽的效果发动时才能发动。从自己的额外卡组·墓地把1只「红莲魔龙」或「琰魔龙 红莲魔」特殊召唤，那个发动的效果无效并破坏。'),
(82382815, 'Champion''s Vigilance', '王者的看破', '王者の看破', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：自己场上有7星以上的通常怪兽存在的场合，可以把以下效果发动。 ●魔法·陷阱卡发动时才能发动。那个发动无效并破坏。 ●自己或者对方把怪兽召唤·反转召唤·特殊召唤之际才能发动。那个无效，那些怪兽破坏。'),
(50643638, 'Chanbar, the Flashy Sportsknight', '灿荣之运动骑士 钱巴尔', NULL, 'Synchro Monster', 'Warrior', 'LIGHT', 8, 2700, 2100, '调整+调整以外的怪兽1只以上 对方场上的怪兽的攻击力下降自己场上的装备魔法卡的数量×400。 「灿荣之运动骑士 钱巴尔」的以下效果1回合各能使用1次。 可以以场上1张其他卡为对象；从自己的手卡·卡组把1张装备魔法卡送去墓地，作为对象的卡破坏。 这张卡在自己墓地存在的场合：可以以自己魔法与陷阱区域的2张表侧表示卡为对象；那些卡破坏，这张卡特殊召唤。');